-- member-service demo seed와 동일한 1~1000번 회원의 주문용 스냅샷입니다.
-- 서비스별 DB가 분리되어 있으므로 Core demo seed에서 명시적으로 동기화합니다.
WITH name_parts AS (
    SELECT
        ARRAY['김','이','박','최','정','강','조','윤','장','임','한','오','서','신','권','황','안','송','전','홍'] AS surnames,
    ARRAY['서준','서연','도윤','하윤','지호','지우','현우','민서','준서','수아',
    '예준','하은','시우','윤서','주원','채원','민준','유진','지훈','은우',
    '도현','서현','건우','예은','우진','소윤','준우','다은','현준','아린',
    '지환','나윤','태윤','가은','승현','지원','시윤','다온','재윤','유나'] AS given_names
    )
    member_id, name, phone, aggregate_version, is_deleted, updated_at
)
SELECT
    member_no,
    surnames[((((member_no * 137) % 800) / array_length(given_names, 1))::integer % array_length(surnames, 1)) + 1]
    || given_names[(((member_no * 137) % 800)::integer % array_length(given_names, 1)) + 1],
    '010-0000-' || lpad(member_no::text, 4, '0'),
    0,
    false,
    current_timestamp
FROM generate_series(1, 1000) AS members(member_no)
    CROSS JOIN name_parts;

CREATE TEMP TABLE demo_store_source (
    seed_id bigint PRIMARY KEY,
    source_id varchar(40) NOT NULL UNIQUE,
    source_area varchar(30) NOT NULL,
    store_name varchar(255) NOT NULL,
    store_address varchar(255) NOT NULL,
    category varchar(30) NOT NULL,
    latitude numeric(9,6) NOT NULL,
    longitude numeric(10,6) NOT NULL
);

-- BEGIN GENERATED DEMO STORES
-- Generated from OpenStreetMap via Overpass API. Do not edit manually.
-- END GENERATED DEMO STORES


    store_id, member_id, store_name, store_address, latitude, longitude, store_phone,
    business_number, category, status, open_time, close_time, next_closing_at,
    is_deleted, updated_at, event_version
)
SELECT
    seed_id,
    seed_id,
    store_name,
    store_address,
    latitude,
    longitude,
    '02-000-' || lpad(seed_id::text, 4, '0'),
    '000-' || lpad(seed_id::text, 2, '0') || '-' || lpad((10000 + seed_id)::text, 5, '0'),
    category,
    'OPEN',
    time '09:00',
    time '22:00',
    date_trunc('day', current_timestamp) + interval '22 hours',
    false,
    current_timestamp,
    0
FROM demo_store_source
ORDER BY seed_id;

    payout_account_id, store_id, bank_name, account_number, account_holder,
    active, is_deleted, updated_at
)
SELECT
    seed_id,
    seed_id,
    CASE seed_id % 5
    WHEN 0 THEN '국민은행'
        WHEN 1 THEN '신한은행'
        WHEN 2 THEN '우리은행'
        WHEN 3 THEN '하나은행'
        ELSE '농협은행'
END,
    '1P32lJFxQqOjJVbl6587VvnRoBDKjAV12ExbDWFG3N2HZ8Yn3bf5nQ==',
    '시연판매자' || lpad(seed_id::text, 3, '0'),
    true,
    false,
    current_timestamp
FROM demo_store_source;

    id, store_id, dish_name, description, category, dish_price, discount_price,
