WITH store_products AS (
    SELECT
        source.*,
        CASE
            WHEN category = 'CAFE_DESSERT' THEN
                (ARRAY['CAKE', 'DESSERT', 'DRINK', 'FRUIT', 'DAIRY', 'DESSERT_BREAD'])[((seed_id % 6) + 1)::integer]
    WHEN category IN ('WESTERN', 'FAST_FOOD') THEN
   (ARRAY['SANDWICH', 'SALAD', 'MEAL_BREAD'])[((seed_id % 3) + 1)::integer]
    WHEN category = 'PIZZA' THEN 'MEAL_BREAD'
    ELSE 'RICE'
END AS product_type
    FROM demo_store_source source
    WHERE seed_id BETWEEN 1 AND 1000
)
    id, store_id, dish_name, description, category, dish_price, discount_price,
    stock_quantity, dish_status, thumbnail_url, pickup_start_time, pickup_end_time,
    registered_at, is_deleted, event_version, updated_at
)
SELECT
    seed_id,
    seed_id,
    store_name || ' ' || CASE product_type
                             WHEN 'CAKE' THEN '시그니처 조각 케이크'
                             WHEN 'DESSERT' THEN '구움과자 모둠 세트'
                             WHEN 'DRINK' THEN '시그니처 음료 2잔 세트'
                             WHEN 'FRUIT' THEN '제철 과일 컵'
                             WHEN 'DAIRY' THEN '수제 그릭요거트 볼'
                             WHEN 'DESSERT_BREAD' THEN '달콤한 크림빵 세트'
                             WHEN 'SANDWICH' THEN '오늘의 샌드위치'
                             WHEN 'SALAD' THEN '신선한 데일리 샐러드'
                             WHEN 'MEAL_BREAD' THEN '든든한 포카치아 세트'
                             ELSE CASE category
                                      WHEN 'CHICKEN' THEN '순살치킨 도시락'
                                      WHEN 'CHINESE' THEN '중화식 볶음밥'
                                      WHEN 'BUNSIK' THEN '떡볶이 김밥 세트'
                                      WHEN 'SOUP_STEW' THEN '오늘의 국밥'
                                      WHEN 'CUTLET_SUSHI' THEN '돈카츠 덮밥'
                                      WHEN 'JOKBAL_BOSSAM' THEN '족발 덮밥'
                                      WHEN 'MEAT' THEN '직화고기 덮밥'
                                      WHEN 'LATE_NIGHT' THEN '매콤 제육덮밥'
                                      WHEN 'ASIAN' THEN '아시안 라이스볼'
                                      WHEN 'LUNCH_BOX' THEN '오늘의 한상 도시락'
                                      ELSE '집밥 한상 도시락'
                                 END
        END,
    CASE product_type
        WHEN 'CAKE' THEN store_name || '의 촉촉한 시트와 부드러운 크림으로 만든 당일 생산 조각 케이크입니다.'
        WHEN 'DESSERT' THEN store_name || '에서 당일 구운 쿠키와 휘낭시에를 다양하게 담은 디저트 세트입니다.'
        WHEN 'DRINK' THEN store_name || '의 대표 원두와 재료로 만든 시그니처 음료 두 잔 구성입니다.'
        WHEN 'FRUIT' THEN store_name || '에서 신선하게 손질한 제철 과일을 한 컵에 담았습니다.'
        WHEN 'DAIRY' THEN store_name || '의 꾸덕한 그릭요거트에 과일과 그래놀라를 곁들인 한 끼 볼입니다.'
        WHEN 'DESSERT_BREAD' THEN store_name || '에서 당일 구운 부드러운 빵에 달콤한 크림을 채운 세트입니다.'
        WHEN 'SANDWICH' THEN store_name || '의 신선한 채소와 풍성한 속재료를 담은 당일 제조 샌드위치입니다.'
        WHEN 'SALAD' THEN store_name || '에서 손질한 채소와 단백질 토핑을 균형 있게 담은 샐러드입니다.'
        WHEN 'MEAL_BREAD' THEN store_name || '의 담백한 반죽에 든든한 토핑을 올려 구운 식사빵 세트입니다.'
        ELSE store_name || '의 ' || CASE category
                                       WHEN 'CHICKEN' THEN '바삭하게 조리한 순살치킨과 밥, 곁들임 반찬을 담은 도시락입니다.'
                                       WHEN 'CHINESE' THEN '불향을 살린 중화식 볶음밥에 매일 준비한 고명을 곁들였습니다.'
                                       WHEN 'BUNSIK' THEN '매콤달콤한 떡볶이와 든든한 김밥을 함께 담은 분식 세트입니다.'
                                       WHEN 'SOUP_STEW' THEN '오랜 시간 우린 육수와 푸짐한 건더기로 완성한 따뜻한 국밥입니다.'
                                       WHEN 'CUTLET_SUSHI' THEN '바삭한 돈카츠와 소스, 밥을 한 그릇에 담은 든든한 덮밥입니다.'
                                       WHEN 'JOKBAL_BOSSAM' THEN '부드럽게 삶은 족발과 채소, 특제 소스를 밥 위에 올린 덮밥입니다.'
                                       WHEN 'MEAT' THEN '불향 가득 구운 고기와 신선한 채소를 밥 위에 푸짐하게 담았습니다.'
                                       WHEN 'LATE_NIGHT' THEN '매콤하게 볶은 제육과 따뜻한 밥을 함께 담아 든든하게 구성했습니다.'
                                       WHEN 'ASIAN' THEN '향신료로 맛을 낸 고기와 채소를 밥에 곁들인 아시안 라이스볼입니다.'
                                       WHEN 'LUNCH_BOX' THEN '오늘 조리한 메인 요리와 계절 반찬을 균형 있게 담은 도시락입니다.'
                                       ELSE '정성껏 조리한 메인 요리와 밥, 계절 반찬을 함께 담은 집밥 도시락입니다.'
            END
        END,
    CASE product_type
        WHEN 'CAKE' THEN '케이크'
        WHEN 'DESSERT' THEN '디저트'
        WHEN 'DRINK' THEN '음료 / 카페'
        WHEN 'FRUIT' THEN '과일류'
        WHEN 'DAIRY' THEN '유제품'
        WHEN 'DESSERT_BREAD' THEN '디저트 빵'
        WHEN 'SANDWICH' THEN '샌드위치'
        WHEN 'SALAD' THEN '샐러드'
        WHEN 'MEAL_BREAD' THEN '식사빵'
        ELSE '밥류'
        END,
    18000, 9900, 1000000, 'ON_SALE', NULL,
    time '18:00', time '21:30', current_timestamp, false, 0, current_timestamp
FROM store_products
    ON CONFLICT (id) DO UPDATE SET
    store_id = EXCLUDED.store_id,
                            dish_name = EXCLUDED.dish_name,
                            description = EXCLUDED.description,
                            category = EXCLUDED.category;

SELECT seed_id, seed_id FROM demo_store_source;

WITH generated_orders AS (
    SELECT
        ((stores.store_id - 1) * 1000 + order_no)::bigint AS order_id,
            stores.store_id,
        order_no,
        dishes.id AS dish_id,
        dishes.dish_name,
        dishes.dish_price,
        ((stores.store_id + order_no - 2) % 1000 + 1)::bigint AS member_id,
    date_trunc('month', current_timestamp) - interval '1 month'
    - ((order_no - 1) % 100) * interval '1 month'
    + ((order_no + stores.store_id) % 25) * interval '1 day'
    + ((order_no + stores.store_id) % 12 + 8) * interval '1 hour' AS created_at,
    dishes.discount_price AS unit_price,
    (1 + order_no % 3)::bigint AS quantity,
    CASE
    WHEN order_no <= 180 THEN 'PICKED_UP'
    WHEN order_no <= 210 THEN 'RESERVED'
    WHEN order_no <= 240 THEN 'PICKUP_READY'
    WHEN order_no <= 255 THEN 'NO_SHOW'
    WHEN order_no <= 285 THEN 'CANCELLED'
    ELSE 'REJECTED'
END AS status
    FROM generate_series(1, 1000) AS stores(store_id)
    CROSS JOIN generate_series(1, 300) AS order_numbers(order_no)
    JOIN public.dishes dishes ON dishes.store_id = stores.store_id
        AND dishes.is_deleted = false
)
    id, member_id, store_id, dish_id, dish_name, member_name, phone, quantity,
    unit_price, total_price, used_point, used_deposit, total_saved_amount,
    status, payment_status,
    pickup_start_at, pickup_end_at, pickup_deadline, pickup_result_at, pickup_code,
    cancel_reason, reject_reason, is_deleted, created_at, updated_at, event_version
)
SELECT
    order_id,
    member_id,
    store_id,
    dish_id,
    dish_name,
    '시연 구매자 ' || lpad(member_id::text, 3, '0'),
    '010-0000-' || lpad(member_id::text, 4, '0'),
    quantity,
    unit_price,
    unit_price * quantity,
    0::numeric(38,2),
        unit_price * quantity,
    (dish_price - unit_price) * quantity,
    status,
    'COMPLETED',
    time '18:00',
    time '21:30',
    created_at + interval '8 hours',
    CASE WHEN status IN ('PICKED_UP', 'NO_SHOW') THEN created_at + interval '8 hours' END,
    CASE WHEN status IN ('RESERVED', 'PICKUP_READY', 'PICKED_UP', 'NO_SHOW')
        THEN lpad((order_id % 1000000)::text, 6, '0') END,
    CASE WHEN status = 'CANCELLED' THEN '구매자 요청으로 취소' END,
    CASE WHEN status = 'REJECTED' THEN 'OUT_OF_STOCK' END,
    false,
    created_at,
    created_at + interval '1 hour',
    0
FROM generated_orders;

SELECT id, member_id, status, updated_at, updated_at
FROM public.orders;

CREATE TEMP TABLE demo_member_charge AS
SELECT
    member_id,
    sum(total_price) FILTER (WHERE status NOT IN ('CANCELLED', 'REJECTED'))
        + 1000000000000 AS charge_amount
FROM public.orders
GROUP BY member_id;

SELECT member_id, member_id, 1000000000000, current_timestamp
FROM demo_member_charge;

    member_id, order_id, payment_id, type, amount, balance_after, created_at
)
SELECT
    member_id, NULL, member_id, 'CHARGE', charge_amount, charge_amount,
    current_timestamp - interval '9 years'
FROM demo_member_charge;

WITH events AS (
    SELECT
        member_id,
        id AS order_id,
        'USE'::varchar AS type,
            total_price AS amount,
        -total_price AS delta,
        created_at,
        0 AS event_order
    FROM public.orders
    UNION ALL
    SELECT
        member_id,
        id,
        'REFUND',
        total_price,
        total_price,
        created_at + interval '1 minute',
    1
FROM public.orders
WHERE status IN ('CANCELLED', 'REJECTED')
    ), balanced AS (
SELECT
    events.*,
    charges.charge_amount
    + sum(delta) OVER (
    PARTITION BY events.member_id
    ORDER BY events.created_at, events.order_id, event_order
    ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
    ) AS balance_after
FROM events
    JOIN demo_member_charge charges USING (member_id)
    )
    member_id, order_id, payment_id, type, amount, balance_after, created_at
)
SELECT member_id, order_id, NULL, type, amount, balance_after, created_at
FROM balanced
ORDER BY member_id, created_at, order_id, event_order;

WITH months AS (
    SELECT
        stores.store_id,
        month_no,
        date_trunc('month', current_timestamp) - month_no * interval '1 month' AS period_start
FROM generate_series(1, 1000) AS stores(store_id)
    CROSS JOIN generate_series(1, 100) AS month_numbers(month_no)
    ), aggregates AS (
SELECT
    months.store_id,
    months.month_no,
    months.period_start,
    months.period_start + interval '1 month' AS period_end,
    count(orders.id)::bigint AS total_order_count,
    coalesce(sum(orders.total_price), 0)::bigint AS gross_amount
FROM months
    LEFT JOIN public.orders orders
ON orders.store_id = months.store_id
    AND orders.status IN ('PICKED_UP', 'NO_SHOW')
    AND orders.created_at >= months.period_start
    AND orders.created_at < months.period_start + interval '1 month'
GROUP BY months.store_id, months.month_no, months.period_start
    )
    id, store_id, settlement_month, period_start, period_end, total_order_count,
    gross_amount, fee_rate, fee_amount, settlement_amount, settlement_status,
    bank_code, account_number, account_holder, failure_reason, created_at, updated_at
)
SELECT
    (store_id - 1) * 100 + month_no,
    store_id,
    to_char(period_start, 'YYYY-MM'),
    period_start,
    period_end,
    total_order_count,
    gross_amount,
    0.0500,
    floor(gross_amount * 0.05)::bigint,
        gross_amount - floor(gross_amount * 0.05)::bigint,
        CASE
            WHEN month_no = 1 THEN 'ACCUMULATING'
            WHEN month_no <= 80 THEN 'COMPLETED'
            WHEN month_no <= 90 THEN 'PROCESSING'
            ELSE 'FAILED'
            END,
    CASE WHEN month_no = 1 THEN NULL ELSE 'DEMO_BANK' END,
    CASE WHEN month_no = 1 THEN NULL ELSE '000000' || lpad(store_id::text, 6, '0') END,
    CASE WHEN month_no = 1 THEN NULL ELSE '시연판매자' || lpad(store_id::text, 3, '0') END,
    CASE WHEN month_no > 90 THEN '시연용 정산 실패' END,
    period_end,
    period_end
FROM aggregates;

    settlement_id, order_id, sales_amount, fee_rate, fee_amount,
    settlement_amount, order_completed_at, created_at
)
SELECT
    (orders.store_id - 1) * 100
        + ((extract(year FROM age(date_trunc('month', current_timestamp) - interval '1 month', date_trunc('month', orders.created_at))) * 12
        + extract(month FROM age(date_trunc('month', current_timestamp) - interval '1 month', date_trunc('month', orders.created_at))))::bigint + 1),
    orders.id,
    orders.total_price::bigint,
    0.0500,
    floor(orders.total_price * 0.05)::bigint,
    orders.total_price::bigint - floor(orders.total_price * 0.05)::bigint,
    orders.pickup_result_at,
    orders.pickup_result_at
FROM public.orders orders
WHERE orders.status IN ('PICKED_UP', 'NO_SHOW');

SELECT member_id, 'LEVEL_5', count(*)::integer, 0, current_timestamp
FROM public.orders
WHERE status = 'PICKED_UP'
GROUP BY member_id;

-- BEGIN EVENT SETTLEMENT PERFORMANCE TEST DATA
-- 주문 완료 이벤트 방식의 월 정산 성능 테스트를 위한 사전 적립 데이터입니다.
--   * 정산 월: 2026-09
--   * 매장 수: 1,000개
--   * 매장별 정산 상세: 450건
--   * 전체 정산 상세: 450,000건
--   * Settlement ID: 900001 ~ 901000
--   * Order ID: 1000001 ~ 1450000
-- 테스트 완료 후 이 블록을 제거하거나, 아래 CLEANUP 블록을 실행하면 됩니다.

    id, store_id, settlement_month, period_start, period_end, total_order_count,
    gross_amount, fee_rate, fee_amount, settlement_amount, settlement_status,
    bank_code, account_number, account_holder, failure_reason, created_at, updated_at
)
SELECT
    (900000 + store_id)::bigint,
        store_id::bigint,
        '2026-09',
    timestamp '2026-09-01 00:00:00',
    timestamp '2026-10-01 00:00:00',
    0,
    0,
    0.1000,
    0,
    0,
    'ACCUMULATING',
    NULL,
    NULL,
    NULL,
    NULL,
    timestamp '2026-09-01 00:00:00',
    timestamp '2026-09-01 00:00:00'
FROM generate_series(1, 1000) AS stores(store_id);

WITH event_settlement_details AS (
    SELECT
        store_id::bigint AS store_id,
            order_no,
        (900000 + store_id)::bigint AS settlement_id,
            (1000000 + (store_id - 1) * 450 + order_no)::bigint AS order_id,
            (
                (10000 + (store_id % 5) * 1000)
                    * (1 + order_no % 3)
                )::bigint AS sales_amount,
            timestamp '2026-09-01 10:00:00'
                + ((order_no - 1) % 20) * interval '1 day'
    + ((order_no + store_id) % 3600) * interval '1 second'
    + interval '8 hours' AS order_completed_at
FROM generate_series(1, 1000) AS stores(store_id)
    CROSS JOIN generate_series(1, 450) AS order_numbers(order_no)
    )
    settlement_id, order_id, sales_amount, fee_rate, fee_amount,
    settlement_amount, order_completed_at, created_at
)
SELECT
    settlement_id,
    order_id,
    sales_amount,
    0.1000,
    floor(sales_amount * 0.1000)::bigint,
        sales_amount - floor(sales_amount * 0.1000)::bigint,
        order_completed_at,
    order_completed_at
FROM event_settlement_details
ORDER BY store_id, order_no;
-- END EVENT SETTLEMENT PERFORMANCE TEST DATA

